function queueMac(userId,args,action,risk,reason,payload={}){return enqueueMacJob({userId,deviceId:args?.deviceId||"primary-mac",action,args:payload,risk,reason})}
const SYNCHRONOUS_TOOL_BUDGET_MS=Math.max(5000,Math.min(15000,Number(process.env.GEORGIE_TOOL_WAIT_MS||12000)));
async function queueMacAndWait(userId,args,action,risk,reason,payload={},timeoutMs=SYNCHRONOUS_TOOL_BUDGET_MS){const job=await queueMac(userId,args,action,risk,reason,payload);const boundedTimeout=Math.max(1000,Math.min(SYNCHRONOUS_TOOL_BUDGET_MS,Number(timeoutMs)||SYNCHRONOUS_TOOL_BUDGET_MS));const deadline=Date.now()+boundedTimeout;while(Date.now()<deadline){const current=(await listMacJobs(userId,100)).find(item=>item.id===job.id);if(current&&["completed","failed"].includes(current.status)){if(current.status==="failed")throw new Error(current.error||`${action} failed`);return current;}await new Promise(resolve=>setTimeout(resolve,300));}return{...job,status:"pending",durable:true,verification:`Mac agent did not confirm within the ${boundedTimeout}ms synchronous budget; the durable job remains available for later verification`};}
