defineTool({name:"sierra.evidence_graph",workforceOnly,description:"Reconstruct a complete ten-stage deal evidence graph from lead through CRM/accounting with stable record IDs, states, timestamps, provenance, confidence, contradictions, freshness, and explicit unknowns. Read-only.",risk:"read",async run({userId,args}){const reference=args?.reference||args?.referenceNumber;if(!reference)throw new Error("A Sierra deal reference is required");const settled=await Promise.allSettled([getSierraDeal(userId,reference),getSierraApplyInventory(userId,{limit:100,status:"all"}),getSierraDocumentManifest(userId,{reference}),getSierraAuditEvents(userId,{reference,limit:200}),getSierraLenderResponses(userId,reference),getSierraOffers(userId,reference),getSierraReconciliationInvariant(userId,{limit:250}),getSierraGuardedLenderConflicts(userId,{reference,limit:50})]);const names=["deal","applyInventory","documentManifest","auditEvents","lenderResponses","offers","reconciliation","guardedConflicts"],sources={};settled.forEach((item,index)=>{sources[names[index]]=item.status==="fulfilled"?item.value:{unavailable:true,error:item.reason instanceof Error?item.reason.message:String(item.reason)}});sources.guardedConflicts=normalizeGuardedConflicts(sources.guardedConflicts,{reference});return buildDealEvidenceGraph({reference,sources})}});
