defineTool({name:"sierra.document_intelligence",workforceOnly,description:"Return read-only, page-cited application and bank-statement intelligence: required fields, protected identity presence, statement coverage, financial metrics, conflicts, confidence, missing evidence, and source provenance.",risk:"read",async run({userId,args}){const reference=args?.reference||args?.referenceNumber||args?.id;if(!reference)throw new Error("A Sierra deal or application reference is required");const [manifest,deal,auditEvents]=await Promise.all([getSierraDocumentManifest(userId,{reference}),getSierraDeal(userId,reference),getSierraAuditEvents(userId,{reference,limit:200})]);return buildDocumentIntelligence({reference,manifest,deal,auditEvents})}});
defineTool({name:"sierra.document_certification",workforceOnly,description:"Run the fail-closed, read-only document certification: canonical inventory, privacy-safe page citations, complete statement metrics, contradiction/unknown register, Ready/Blocked/Next Action, durable workspace read-back, and an independent second read.",risk:"read",async run({userId,args}){const reference=args?.reference||args?.referenceNumber||args?.id;if(!reference)throw new Error("A Sierra deal or application reference is required");const [intelligence,graph,tasks,approvals]=await Promise.all([registry.get("sierra.document_intelligence").run({userId,args:{reference}}),registry.get("sierra.evidence_graph").run({userId,args:{reference}}),listTasks(userId,{status:"open",limit:200}),listApprovals(userId,{status:"pending",limit:200})]);return certifyDocumentIntelligence({userId,reference,intelligence,graph,tasks,approvals})}});
defineTool({name:"sierra.deal_workspace",workforceOnly,description:"Open or refresh one persistent Deal Intelligence Workspace with page-cited documents, current stage, blockers, underwriting evidence, lender fit, conflicts, approvals, tasks, next action, and a source-linked timeline.",risk:"read",async run({userId,args}){const reference=args?.reference||args?.referenceNumber||args?.id;if(!reference)throw new Error("A Sierra deal or application reference is required");if(args?.refresh===false){const stored=await getDealWorkspace(userId,reference);if(stored)return stored;}const [graph,documentIntelligence,tasks,approvals]=await Promise.all([registry.get("sierra.evidence_graph").run({userId,args:{reference}}),registry.get("sierra.document_intelligence").run({userId,args:{reference}}),listTasks(userId,{status:"open",limit:200}),listApprovals(userId,{status:"pending",limit:200})]);return refreshDealWorkspace(userId,{reference,graph,documentIntelligence,tasks,approvals})}});
