defineTool({name:"sierra.investigation_open",workforceOnly,description:"Open one durable investigation by exact ID as a compact cursor-addressable report page. Raw evidence is excluded by default and available only through an explicit contract cursor, preventing oversized turns and enabling resumable delivery.",risk:"read",async run({userId,args}){const id=String(args?.investigationId||args?.requestId||args?.id||"").trim();if(!id)throw new Error("An investigation ID is required");let artifact=await openInvestigationArtifact(userId,id);if(!artifact){const legacy=(await listDiagnosticPlans(userId,{limit:40})).find(item=>item.requestId===id);if(legacy)artifact=await persistInvestigationArtifact(userId,legacy);}if(!artifact)throw new Error(`Investigation artifact ${id} was not found in durable artifact storage or the legacy diagnostic plan store`);return investigationArtifactPage(artifact,{cursor:args?.cursor,includeRaw:Boolean(args?.includeRaw),maxBytes:args?.maxBytes})}});
