defineTool({name:"sierra.diagnostic_investigation",workforceOnly,description:"Run and durably retain one read-only cross-system Sierra investigation. Each source executes independently and the final report synthesizes coverage, freshness, contradictions, and missing evidence under a request ID.",risk:"read",async run({userId,args}){return runDurableDiagnosticPlan(userId,args||{},async(name,toolArgs)=>{const tool=registry.get(name);if(!tool)throw new Error(`Required diagnostic tool is unavailable: ${name}`);if(tool.risk!=="read")throw new Error(`Diagnostic plans cannot execute non-read tool: ${name}`);try{return{ok:true,result:await Promise.race([tool.run({userId,args:toolArgs}),new Promise((_,reject)=>setTimeout(()=>reject(new Error(`${name} exceeded its 12000ms diagnostic timeout`)),12000))])}}catch(error){return{ok:false,error:error instanceof Error?error.message:String(error)}}})}});
