defineTool({name:"campaigns.prepare_status_change",description:"Prepare a Smartlead campaign start, pause, or stop action for explicit approval. This does not change the provider.",risk:"low_risk_write",async run({userId,args}){const campaignId=String(args?.campaignId||"").trim(),status=String(args?.status||"").trim().toUpperCase();if(!/^\d+$/.test(campaignId))throw new Error("A numeric Smartlead campaign ID is required");if(!["START","PAUSED","STOPPED"].includes(status))throw new Error("Status must be START, PAUSED, or STOPPED");return createApprovalRequest(userId,{domain:"campaigns",actionType:"smartlead_campaign_status",title:`Smartlead campaign ${campaignId}: ${status}`,summary:`Prepare provider-direct ${status} for Smartlead campaign ${campaignId}. No action occurs until explicit approval.`,evidence:{campaignId,status},risk:status==="START"?"high":"medium",reversible:status!=="STOPPED",verificationMethod:"Re-read provider campaign inventory and require the requested status.",rollbackPlan:status==="START"?"Pause the same campaign if verification or safety checks fail.":"No automatic rollback; require a new approved status action."})}});
defineTool({name:"campaigns.execute_approved_status_change",description:"Execute one explicitly approved Smartlead campaign status change and verify the provider state. Requires approval ID and idempotency key.",risk:"external_side_effect",async run({userId,args}){const approval=await getApprovalRequest(userId,args?.approvalId);if(!approval||approval.status!=="approved")throw new Error("An approved campaign change request is required");if(approval.actionType!=="smartlead_campaign_status")throw new Error("Approval is not for a Smartlead campaign status change");if(!String(args?.idempotencyKey||"").trim())throw new Error("Idempotency key is required");return updateSmartleadCampaignStatus(args?.campaignId,args?.status)}});
